//! 元の主解から目的改善行を加えて既存Rust座標修復を試す診断専用例。
#[path="support/resource_dynamic_repair_core.rs"]mod dynamic;
use dynamic::Repair;
use mip_codex::{model::Row,solve::Result};
use std::time::{Instant,Duration};
fn main(){
 let args:Vec<_>=std::env::args().collect();
 if args.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}
 let wall=Instant::now();let model=mip_codex::mps::read(&args[1]).unwrap();let input:serde_json::Value=serde_json::from_reader(std::fs::File::open(&args[2]).unwrap()).unwrap();let point:Vec<_>=model.variables.iter().map(|v|input["values"][&v.name].as_f64().unwrap()).collect();let original=Repair::new(&model);assert!(original.candidate_check(&point));let sign=if model.maximize{-1.}else{1.};let current=sign*model.objective(&point);let scale=model.variables.iter().map(|v|v.objective.abs()).fold(0f64,f64::max);assert!(scale>0.&&scale.is_finite());let step=model.variables.iter().map(|v|v.objective.abs()).filter(|&v|v>0.).min_by(f64::total_cmp).unwrap();let target=(current-step-sign*model.offset)/scale;
 let mut work=model.clone();work.decimal_source=None;work.rows.push(Row{integer_bounds:None,name:"internal_diagnostic_objective_target".into(),lower:None,upper:Some(target),coefficients:model.variables.iter().enumerate().filter(|(_,v)|v.objective!=0.).map(|(j,v)|(j,sign*v.objective/scale)).collect(),exact_integral:false,exact_coefficients:false,exact_coefficient_flags:vec![],lower_enclosure:None,upper_enclosure:Some([target,target])});
 let mut repair=Repair::new(&work);let lower:Vec<_>=model.variables.iter().map(|v|v.lower).collect();let upper:Vec<_>=model.variables.iter().map(|v|v.upper).collect();let seconds:f64=args[3].parse().unwrap();let end=Instant::now()+Duration::from_secs_f64(seconds);let seed:u64=args[5].parse().unwrap();let candidate=repair.search(&point,&lower,&upper,end,100_000_000,seed);let mut objective=None;
 if let Some(x)=candidate{if original.candidate_check(&x)&&sign*model.objective(&x)<current{objective=Some(model.objective(&x));let r=Result{status:"feasible_resource_priced_repair_diagnostic".into(),objective,values:Some(model.variables.iter().zip(x).map(|(v,x)|(v.name.clone(),x)).collect()),..Result::default()};serde_json::to_writer(std::fs::File::create(&args[4]).unwrap(),&r).unwrap();}}
 println!("{}",serde_json::json!({"candidate":objective.is_some(),"objective":objective,"target":target,"normalized_previous":current,"calls":repair.stats.calls,"moves":repair.stats.moves,"work":repair.stats.work,"wall_seconds":wall.elapsed().as_secs_f64(),"budget_seconds":seconds,"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));
}
